function cuttingSaveRecord(array $c,array $o,?array $prior,array $state,array $calculation,string $status):array{
 $id=$prior['id']??uid();$revision=($prior['revision']??0)+1;
 if($prior)query('UPDATE cutting_plans SET revision=?,status=?,state_json=?,calculation_json=?,actor_id=? WHERE id=? AND company_id=?',[$revision,$status,j($state),j($calculation),$_SESSION['user_id'],$id,$c['id']]);else query('INSERT INTO cutting_plans (id,company_id,order_id,revision,status,state_json,calculation_json,actor_id) VALUES (?,?,?,?,?,?,?,?)',[$id,$c['id'],$o['id'],$revision,$status,j($state),j($calculation),$_SESSION['user_id']]);
 manufacturingRevision($c,'cutting',$id,$revision,['status'=>$status,'state'=>$state,'calculation'=>$calculation]);audit('cutting_'.$status,['id'=>$id,'revision'=>$revision,'order_id'=>$o['id']]);return ['id'=>$id,'revision'=>$revision,'status'=>$status,'state'=>$state,'calculation'=>$calculation];
}
function cuttingOrder(array $input):array{$o=orderRecord(textField($input,'order_id',32,true));$o['route']=decode($o['route']);return $o;}
function cuttingAction(string $action,array $input):array{
 $c=permit(in_array($action,['cutting_event','cutting_tasks'],true)?['owner','technologist','chief','foreman','worker','qc']:['owner','technologist','chief','foreman']);manufacturingRequireStorage();
 if($action==='cutting_asset_save')return command($action,$input,function(array $c)use($input){if(!in_array($c['role'],['owner','technologist','chief','foreman'],true))fail('Нет права менять данные раскроя',403);$assets=cuttingAssets($c);$id=manufacturingId($input,'id',60);$old=$assets[$id]??null;checkRevision($old['revision']??0,$input);$v=cuttingAssetNormalize($input,$c,$old);if($old&&$old['kind']==='roll'){$used=(int)(one("SELECT SUM(length_mm) q FROM cutting_roll_reservations WHERE company_id=? AND roll_id=? AND state IN ('reserved','consumed')",[$c['id'],$id])['q']??0);if($v['state']['length_mm']<$used)fail('Исходная длина меньше закреплённого или израсходованного материала');if($used)foreach(['material_id','color','shade','width_mm'] as $f)if($v['state'][$f]!==$old['state'][$f])fail('Свойства использованного рулона закреплены; создайте другую физическую партию');}if($old&&$old['kind']!==$v['kind'])fail('Вид сохранённых данных не меняется');$rev=($old['revision']??0)+1;
  if($old)query('UPDATE cutting_assets SET revision=?,state_json=?,actor_id=? WHERE id=? AND company_id=?',[$rev,j($v['state']),$_SESSION['user_id'],$id,$c['id']]);else query('INSERT INTO cutting_assets (id,company_id,kind,revision,state_json,actor_id) VALUES (?,?,?,?,?,?)',[$id,$c['id'],$v['kind'],$rev,j($v['state']),$_SESSION['user_id']]);manufacturingRevision($c,'cutting_asset',$id,$rev,$v);audit('cutting_asset_saved',['id'=>$id,'kind'=>$v['kind'],'revision'=>$rev]);return ['saved'=>true,'id'=>$id,'revision'=>$rev];});
 if($action==='cutting_tasks'){$items=[];$worker=companyWorkerId($c);foreach(rows("SELECT id FROM cutting_plans WHERE company_id=? AND status IN ('released','in_progress') ORDER BY created_at",[$c['id']]) as $row){$record=cuttingRecord($c,$row['id']);if($c['role']==='worker'&&!in_array($worker,$record['state']['workers'],true))continue;$o=orderRecord($record['order_id']);$record['order']=['id'=>$o['id'],'title'=>$o['title'],'product'=>$o['product'],'variants'=>goalVariants($o)];unset($record['calculation']['assets_snapshot']);$items[]=$c['role']==='owner'?$record:cuttingRedact($record);}return ['items'=>$items];}
 $o=cuttingOrder($input);$assets=cuttingAssets($c);
 if($action==='cutting_open'){
  $plans=[];foreach(rows('SELECT id FROM cutting_plans WHERE company_id=? AND order_id=? ORDER BY created_at DESC',[$c['id'],$o['id']]) as $p)$plans[]=cuttingRecord($c,$p['id']);$record=!empty($input['id'])?cuttingRecord($c,textField($input,'id',32,true)):($plans[0]??null);if($record&&$record['order_id']!==$o['id'])fail('Раскрой относится к другой цели',403);$out=['record'=>$record??['id'=>null,'revision'=>0,'status'=>'draft','state'=>cuttingDefault($c,$o),'calculation'=>null],'plans'=>$plans,'assets'=>array_values($assets),'variants'=>goalVariants($o),'order_revision'=>(int)$o['revision'],'company_revision'=>$c['revision'],'remaining'=>cuttingWaveRemaining($c,$o,$record&&in_array($record['status'],['draft','review','approved'],true)?$record['id']:null)];return $c['role']==='owner'?$out:cuttingRedact($out);
 }
 if(in_array($action,['cutting_calculate','cutting_options'],true)){
  if((int)($input['order_revision']??-1)!==(int)$o['revision'])fail('Цель изменилась. Откройте раскрой заново.',409);$state=cuttingNormalize($input['state']??[],$c,$o,$assets);$id=textField($input,'id',32);if($id){$record=cuttingRecord($c,$id);if($record['order_id']!==$o['id'])fail('Чужая цель',403);if($c['role']!=='owner')foreach(['pay_rule_id','pay_basis','manual_basis_cents','manual_basis_unit','pay_mode','material_cost_mode','material_expense_id'] as $k)$state[$k]=$record['state'][$k]??$state[$k];}
  if($action==='cutting_options'){$options=[];foreach(['fast'=>'Быстрый запуск','economical'=>'Экономный расход','balanced'=>'Сбалансированный'] as $strategy=>$name){$candidate=cuttingPropose($state,$c,$o,$assets,$strategy);$options[]=['name'=>$name,'state'=>$candidate,'calculation'=>cuttingCalculate($candidate,$c,$o,$assets,$id?:null,$strategy)];}$out=['options'=>$options];}else $out=['calculation'=>cuttingCalculate($state,$c,$o,$assets,$id?:null)];return $c['role']==='owner'?$out:cuttingRedact($out);
 }
 return command($action,$input,function(array $c)use($action,$input){$o=cuttingOrder($input);$assets=cuttingAssets($c);$id=textField($input,'id',32);$prior=$id?cuttingRecord($c,$id,true):null;if($prior&&$prior['order_id']!==$o['id'])fail('Раскрой относится к другой цели',403);checkRevision($prior['revision']??0,$input);
  if($action==='cutting_event')return cuttingProductionEvent($c,$o,$prior,$input);
  if((int)($input['order_revision']??-1)!==(int)$o['revision'])fail('Цель или комплектация изменились. Обновите расчёт.',409);
  if($action==='cutting_save'){
   if($prior&&in_array($prior['status'],['released','in_progress','completed','cancelled'],true))fail('Выпущенный расчёт сохраняет историю. Создайте следующую волну или копию.');$raw=$input['state']??[];
   if($c['role']!=='owner')foreach(['pay_rule_id','pay_basis','manual_basis_cents','manual_basis_unit','pay_mode','material_cost_mode','material_expense_id'] as $k)$raw[$k]=$prior['state'][$k]??cuttingDefault($c,$o)[$k];$state=cuttingNormalize($raw,$c,$o,$assets);$state['approvals']=[];$calc=cuttingCalculate($state,$c,$o,$assets,$id?:null);$r=cuttingSaveRecord($c,$o,$prior,$state,$calc,'draft');return $c['role']==='owner'?$r:cuttingRedact($r);
  }
  if(!$prior)fail('Сначала сохраните расчёт');$state=$prior['state'];$calc=$prior['calculation'];
  if($action==='cutting_cancel'){
   if(!in_array($c['role'],['owner','chief'],true))fail('Отмену подтверждает начальник производства',403);if(in_array($prior['status'],['in_progress','completed'],true)||!empty($state['execution']))fail('Начатая работа не отменяется: сохраните факт и создайте новую волну');$balances=preparationBalances($c,$o);foreach($calc['credit_allocations']??[] as $lot=>$q)if(($balances[$lot]['issued']??0)>0)fail('По обеспечению этой волны уже начат пошив; сохраните факт и измените будущую потребность');query("UPDATE cutting_roll_reservations SET state='released' WHERE company_id=? AND plan_id=? AND state='reserved'",[$c['id'],$id]);foreach(rows("SELECT tranche_id,kind,quantity FROM preparation_movements WHERE company_id=? AND order_id=? AND batch_key=? AND kind IN ('cut_claim','cut_unclaim')",[$c['id'],$o['id'],'cutting-'.$id]) as $claim)if($claim['kind']==='cut_claim')preparationMovement($c,$o,$claim['tranche_id'],'cutting-'.$id,'cut_unclaim',(int)$claim['quantity'],['cancelled_cutting_id'=>$id]);$r=cuttingSaveRecord($c,$o,$prior,$state,$calc,'cancelled');if(function_exists('cuttingSyncPreparation'))cuttingSyncPreparation($c,$o,$r);return ['saved'=>true,'revision'=>$r['revision']];
  }
  if(!in_array($prior['status'],['draft','review','approved'],true))fail('Этот расчёт уже выпущен или закрыт');$fresh=cuttingCalculate($state,$c,$o,$assets,$id);if($fresh['status']!=='feasible')fail($fresh['errors'][0]['message']??'Расчёт неполон');if(($calc['input_versions']??null)!==$fresh['input_versions'])fail('Исходные данные изменились. Сохраните новую редакцию перед согласованием.',409);
  if($action==='cutting_approve'){$approvals=$state['approvals']??[];$stage=['foreman','technologist','chief'][count($approvals)]??null;if(!$stage)fail('Все этапы уже согласованы');if($c['role']!=='owner'&&$c['role']!==$stage)fail('Следующий этап согласует '.$stage,403);$approvals[]=['stage'=>$stage,'actor_id'=>$_SESSION['user_id'],'at'=>date('c')];$state['approvals']=$approvals;$r=cuttingSaveRecord($c,$o,$prior,$state,$fresh,count($approvals)===3?'approved':'review');return ['saved'=>true,'id'=>$id,'revision'=>$r['revision']];}
  if($action==='cutting_release'){
   if(!in_array($c['role'],['owner','chief'],true))fail('Выпуск подтверждает начальник производства',403);if($prior['status']!=='approved')fail('Согласуйте расчёт у мастера, технолога и начальника');foreach($fresh['roll_allocations'] as $lay=>$rolls)foreach($rolls as $roll=>$length)query('INSERT INTO cutting_roll_reservations (id,company_id,plan_id,lay_id,roll_id,length_mm,state) VALUES (?,?,?,?,?,?,?)',[uid(),$c['id'],$id,$lay,$roll,$length,'reserved']);foreach($fresh['credit_allocations']??[] as $lot=>$q)preparationMovement($c,$o,$lot,'cutting-'.$id,'cut_claim',$q,['cutting_id'=>$id]);$fresh['assets_snapshot']=$assets;$r=cuttingSaveRecord($c,$o,$prior,$state,$fresh,'released');if(function_exists('cuttingSyncPreparation'))cuttingSyncPreparation($c,$o,$r);return ['saved'=>true,'id'=>$id,'revision'=>$r['revision']];
  }
  fail('Действие раскроя не найдено');
 });
}
function cuttingProductionEvent(array $c,array $o,?array $record,array $input):array{
 if(!$record||!in_array($record['status'],['released','in_progress','completed'],true))fail('Сначала выпустите согласованный расчёт');$state=$record['state'];$layId=textField($input,'lay_id',60,true);$lay=array_column($record['calculation']['lays'],null,'id')[$layId]??null;if(!$lay)fail('Настил не найден');$kind=textField($input,'kind',24,true);if(in_array($kind,['quality','rework'],true)&&!in_array($c['role'],['owner','qc'],true))fail('Качество подтверждает ОТК',403);$worker=companyWorkerId($c);if($c['role']==='worker'&&!in_array($worker,$state['workers'],true))fail('Это задание другого исполнителя',403);if($c['role']==='qc'&&!in_array($kind,['quality','rework','transfer'],true))fail('Контролю доступна приёмка и передача',403);
 $execution=$state['execution'][$layId]??['state'=>'planned','cut'=>[],'accepted'=>[],'rework'=>[],'scrap'=>[],'transferred'=>[]];$details=['reason'=>textField($input,'reason',600)];
 if(in_array($kind,['start','pause','resume'],true)){
  if(in_array($kind,['start','resume'],true))manufacturingAssertResourcesFree($c,$state['workers'],array_map(fn($key)=>substr($key,2),array_values(array_filter($lay['resource_keys']??[],fn($key)=>str_starts_with($key,'r:')))),null,$record['id'],$layId);if($kind==='start'){$assets=cuttingAssets($c);foreach($lay['rolls']??[] as $allocation){$roll=$assets[$allocation['roll_id']]['state']??null;if(!$roll||!$roll['accepted']||$roll['archived'])fail('Материал больше не подтверждён для запуска; уточните партию');}if($execution['state']!=='planned')fail('Настил уже начат');$execution['started_at']=date('c');$execution['state']='running';}elseif($kind==='pause'){$execution['state']='paused';if(!$details['reason'])fail('Укажите причину паузы');}else{if($execution['state']!=='paused')fail('Настил не находится на паузе');$execution['state']='running';}
 }elseif(in_array($kind,['cut','quality','transfer'],true)){
  if($execution['state']==='planned')fail('Отметьте начало настила');$variant=textField($input,'variant_id',60,true);$total=$lay['output'][$variant]??0;if(!$total)fail('Вариант отсутствует в настиле');$q=numberField($input,'quantity',1,$total);$details+=['variant_id'=>$variant,'quantity'=>$q];
  if($kind==='cut'){if(($execution['cut'][$variant]??0)+$q>$total)fail('Превышен выпуск настила');$execution['cut'][$variant]=($execution['cut'][$variant]??0)+$q;}
  elseif($kind==='quality'){$accepted=numberField($input,'accepted',0,$q);$rework=numberField($input,'rework',0,$q);$scrap=numberField($input,'scrap',0,$q);if($accepted+$rework+$scrap!==$q)fail('Принято + доработка + брак должны равняться проверенному количеству');$checked=($execution['accepted'][$variant]??0)+($execution['rework'][$variant]??0)+($execution['scrap'][$variant]??0);if($checked+$q>($execution['cut'][$variant]??0))fail('Проверка превышает выпущенный объём');if(($rework||$scrap)&&!$details['reason'])fail('Укажите причину дефекта');foreach(['accepted'=>$accepted,'rework'=>$rework,'scrap'=>$scrap] as $field=>$amount)$execution[$field][$variant]=($execution[$field][$variant]??0)+$amount;$details+=compact('accepted','rework','scrap');}
  else{if(($execution['transferred'][$variant]??0)+$q>($execution['accepted'][$variant]??0))fail('Передать можно только принятый годный крой');$execution['transferred'][$variant]=($execution['transferred'][$variant]??0)+$q;}
 }elseif($kind==='rework'){
  $variant=textField($input,'variant_id',60,true);$q=numberField($input,'quantity',1,100000);if($q>($execution['rework'][$variant]??0))fail('Превышен остаток доработки');if(!$details['reason'])fail('Укажите основание повторной приёмки');$execution['rework'][$variant]-=$q;$execution['accepted'][$variant]=($execution['accepted'][$variant]??0)+$q;$details+=['variant_id'=>$variant,'quantity'=>$q];
 }else fail('Неизвестное событие раскроя');
 $layDone=true;foreach($lay['output'] as $v=>$q)if(($execution['transferred'][$v]??0)+($execution['scrap'][$v]??0)<$q||($execution['rework'][$v]??0)>0)$layDone=false;if($layDone)$execution['state']='completed';$state['execution'][$layId]=$execution;$done=true;foreach($record['calculation']['lays'] as $l){$ex=$state['execution'][$l['id']]??[];foreach($l['output'] as $v=>$q)if(($ex['transferred'][$v]??0)+($ex['scrap'][$v]??0)<$q||($ex['rework'][$v]??0)>0)$done=false;}
 if($kind==='start')query("UPDATE cutting_roll_reservations SET state='consumed' WHERE company_id=? AND plan_id=? AND lay_id=? AND state='reserved'",[$c['id'],$record['id'],$layId]);
 $event=uid();query('INSERT INTO cutting_events (id,company_id,plan_id,lay_id,kind,state_json,actor_id) VALUES (?,?,?,?,?,?,?)',[$event,$c['id'],$record['id'],$layId,$kind,j($details),$_SESSION['user_id']]);$r=cuttingSaveRecord($c,$o,$record,$state,$record['calculation'],$done?'completed':'in_progress');if(function_exists('cuttingSyncPreparation'))cuttingSyncPreparation($c,$o,$r);return ['saved'=>true,'event_id'=>$event,'id'=>$record['id'],'revision'=>$r['revision']];
}
